import java.util.*;

public class Solution {
    public int getMinimumTime(int[] time, int[][] edges, int[] fruits, int[][] queries) {
        int N = time.length;
        List<Integer>[] graph = new List[N];
        for (int i = 0; i < N; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] minTime = new int[N];
        Arrays.fill(minTime, Integer.MAX_VALUE);
        minTime[0] = 0;
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(0);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : graph[u]) {
                if (minTime[v] > minTime[u] + time[v]) {
                    minTime[v] = minTime[u] + time[v];
                    queue.offer(v);
                }
            }
        }

        int[] queriesTime = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int from = queries[i][0], to = queries[i][1];
            queriesTime[i] = minTime[to] - minTime[from] + fruits[from];
        }

        return Arrays.stream(queriesTime).max().getAsInt();
    }
}

