import re

def escape_html(text):
    mapping = [
        (r"&", "&amp;"),
        (r"<", "&lt;"),
        (r">", "&gt;"),
        (r"'", "&#x27;"),
        (r'"', "&quot;"),
    ]

    parts = re.split(r"('|\")", text)

    if len(parts) > 1:
        for i in range(1, len(parts), 2):
            if parts[i] == "'":
                parts[i] = "&#x27;"
            else:
                parts[i] = "&quot;"

    for r, s in mapping:
        parts = [re.sub(r, s, part) for part in parts]

    return "".join(parts)

