import sys

def quick_sort(arr):
    """
    Implementation of quick sort algorithm.
    """
    if len(arr) <= 1:
        return arr
    pivot = arr[0]
    left, right = [], []
    for x in arr[1:]:
        if x < pivot:
            left.append(x)
        else:
            right.append(x)
    return quick_sort(left) + [pivot] + quick_sort(right)

def main():
    arr = list(range(10000))
    arr = quick_sort(arr)

